def edgeprof(fname):
    im=Image.open(fname).convert('RGB'); px=im.load()
    left={}; right={}
    for y in range(150,270):
        for x in range(280,360):
            r,g,b=px[x,y]
            if (r+g+b)/3 < 95:
                left[y]=x; break
        for x in range(360,280,-1):
            r,g,b=px[x,y]
            if (r+g+b)/3 < 95:
                right[y]=x; break
    return left,right
pl={'side_007':191.40,'side_008':196.53,'side_009':199.51}
E={f:edgeprof(f'/home/robot/captures/{f}.jpg') for f in pl}
