    l,r=E[f]
    return {y:r[y]-l[y] for y in l if y in r}
W={f:width(f) for f in pl}
import math
def fit(fA,fB):
    pA,pB=pl[fA],pl[fB]
    WA,WB=W[fA],W[fB]
    best=None
    a=0.85
    while a<=1.01:
        b=pB-a*pA
        # correlate width profiles over yA in [pA+4, 250]
        va=[];vb=[]
        y=pA+4
        while y<250:
            yB=a*y+b; y0=int(yB); fr=yB-y0
