from PIL import Image
pl={'side_007':191.40,'side_008':196.53,'side_009':199.51}
def prof(f):
    im=Image.open('/home/robot/captures/%s.jpg'%f).convert('RGB'); px=im.load()
    p=[]
    for y in range(180,258):
        s=0
        for x in range(302,342):
            r,g,b=px[x,y]; s+=(r+g+b)/3
        p.append(s/40)
    return p
def highpass(p,w=7):
    out=[]
    for i in range(len(p)):
        a=max(0,i-w); b=min(len(p),i+w+1)
        out.append(p[i]-sum(p[a:b])/(b-a))
    return out
def pitch(f):
    p=prof(f); y0=int(pl[f])-180+2
    p=p[y0:]
    hp=highpass(p)
    n=len(hp)
    best=None
    for lag in range(3,20):
        s=sum(hp[i]*hp[i+lag] for i in range(n-lag))
        if best is None or s>best[1]: best=(lag,s)
    # parabolic refine around best lag
    l0=best[0]
    def ac(lag): return sum(hp[i]*hp[i+lag] for i in range(n-lag))
    y1,y2,y3=ac(l0-1),ac(l0),ac(l0+1)
    d=(y1-y3)/(2*(y1-2*y2+y3))
    return l0+d, n
for f in pl:
    print(f, pitch(f))
